CREATE OR REPLACE FUNCTION public.org_members_list() RETURNS TABLE(member_id uuid,user_id uuid,full_name text,email text,role text,status text,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT m.id,m.user_id,trim(p.first_name||' '||p.last_name),p.email,m.role,m.status,m.created_at FROM public.organization_members m LEFT JOIN public.profiles p ON p.id=m.user_id WHERE m.organization_id=public.current_org() AND m.status='active' AND public.org_role(m.organization_id) IN ('owner','manager') ORDER BY CASE m.role WHEN 'owner' THEN 0 WHEN 'manager' THEN 1 ELSE 2 END,m.created_at $$;